/* eslint-disable react-hooks/exhaustive-deps */
import { memo, useEffect, useMemo, useRef } from "react";
import * as THREE from "three";
import { GLTFLoader } from "three/examples/jsm/loaders/GLTFLoader";
import styles from "./Robot.module.scss";
import { isSafari } from "../../utils/Utils";

type RobotProps = {
  positionX: number;
  positionY: number;
  path: string;
  speechText?: string;
};

enum RobotAnimation {
  Greet = 0,
  ArmRaised = 1,
  Idle = 2,
  Walk = 3,
  Welcome = 4,
}

export default memo(function Robot(props: RobotProps): JSX.Element {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const mixerRef = useRef<THREE.AnimationMixer | null>(null);
  const isProjects: boolean = useMemo(
    () => props.path.includes("projects"),
    [props.path],
  );

  useEffect(() => {
    if (!containerRef.current) return;

    // Scene
    const scene = new THREE.Scene();

    // Camera
    const camera = new THREE.PerspectiveCamera(
      75,
      containerRef.current.clientWidth / containerRef.current.clientHeight,
      0.1,
      1000,
    );
    camera.position.z = 300;
    camera.position.y = 150;
    camera.position.x = 0;

    // Renderer
    const renderer = new THREE.WebGLRenderer({ alpha: true });
    renderer.setSize(
      containerRef.current.clientWidth,
      containerRef.current.clientHeight,
    );
    renderer.setClearColor(0x000000, 0); // Set background to transparent
    renderer.shadowMap.enabled = true;
    containerRef.current.appendChild(renderer.domElement);

    // Load 3D Model
    const loader = new GLTFLoader();
    loader.load(
      process.env.PUBLIC_URL + "/models/robot.glb",
      (gltf) => {
        const modelRobot = gltf.scene;
        modelRobot.position.set(0, 0, 0); // Position the model in front of the camera
        scene.add(modelRobot);

        // Enable shadows for the model
        modelRobot.traverse((child) => {
          if ((child as THREE.Mesh).isMesh) {
            child.castShadow = true; // The model casts shadows
            child.receiveShadow = true; // The model receives shadows
          }
        });

        scene.add(modelRobot);

        // Animation Mixer
        const mixer = new THREE.AnimationMixer(modelRobot);
        mixerRef.current = mixer;

        // Play Idle animation by default
        if (gltf.animations.length > 2) {
          const action = mixer.clipAction(
            gltf.animations[RobotAnimation.Idle],
            modelRobot,
          );
          action.play();
        }

        // Animation Loop
        const clock = new THREE.Clock();
        const animate = () => {
          requestAnimationFrame(animate);

          const delta = clock.getDelta();
          mixer.update(delta);

          renderer.render(scene, camera);
        };

        animate();
      },
      undefined,
      (error) => {
        console.error("An error happened while loading the model", error);
      },
    );

    // Lights
    const ambientLight = new THREE.AmbientLight(0xffffff, 2);
    scene.add(ambientLight);

    const directionalLight = new THREE.DirectionalLight(0xffffff, 1);
    directionalLight.position.set(0, 10, 10); // Position the light behind and above the camera
    directionalLight.castShadow = true;
    scene.add(directionalLight);

    // Cleanup on unmount
    return () => {
      if (containerRef.current) {
        containerRef.current.removeChild(renderer.domElement);
      }
    };
  }, []);

  return (
    <div
      ref={containerRef}
      style={{
        transform: !isProjects
          ? `translate(${props.positionX}px, ${props.positionY}px)`
          : "translate(0, calc(100dvh - 100%))",
        transition: isSafari()
          ? "none"
          : "transform 1s cubic-bezier(0.34, 1.56, 0.64, 1)",
        width: "150px",
        height: "150px",
        position: "absolute",
        zIndex: 9999,
        pointerEvents: "none",
      }}
    >
      {props.speechText && (
        <div
          className={styles.speechBubble}
          ref={(el) => {
            if (el) {
              const rect = el.getBoundingClientRect();
              const viewportWidth = window.innerWidth;
              const viewportHeight = window.innerHeight;

              // Si la bulle dépasse l'écran à droite
              if (rect.right > viewportWidth) {
                el.style.left = "-70%";
              }

              // Si la bulle dépasse l'écran à gauche
              if (rect.left < 0) {
                el.style.left = "100%";
              }

              // Si la bulle dépasse l'écran en bas
              if (rect.bottom > viewportHeight) {
                el.style.top = "-70%";
              }
            }
          }}
        >
          {props.speechText}
        </div>
      )}
    </div>
  );
});
